const app = document.querySelector('#app');
const STORAGE_KEY = 'wingerIQ.progress.v1';
const baseProgress = { onboarded:false, completedLessons:0, completedModules:[], correct:0, attempts:0, scenarios:0, streak:1, highestMatchIQ:0, scores:{positioning:20,scanning:15,movement:18,onevone:16,combination:14,finalThird:12,pressing:15,transition:14}, lastVisit:null };
let state = loadProgress();
let currentView = state.onboarded ? 'dashboard' : 'welcome';
let dailySession = null;

function loadProgress(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}');const migrated=Array.isArray(saved.completedModules)?saved.completedModules:[];return {...baseProgress,...saved,completedModules:migrated,scores:{...baseProgress.scores,...(saved.scores||{})}}}catch{return structuredClone(baseProgress)}}
function saveProgress(){state.lastVisit=new Date().toISOString();localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}
function overall(){return Math.round(Object.values(state.scores).reduce((a,b)=>a+b,0)/8)}
function accuracy(){return state.attempts?Math.round(state.correct/state.attempts*100):0}
function rank(){const s=overall();return s>=92?'Pro-Level IQ':s>=82?'Elite':s>=70?'Advanced':s>=55?'First Team':s>=35?'Development':'Academy'}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}

function welcome(){app.innerHTML=`<main class="welcome"><section class="welcome-card"><div class="brand"><span class="brand-mark">W</span><span>WINGER IQ</span></div><h1>SEE IT.<br>BEAT IT.</h1><p class="welcome-quote">Great wingers don't react to the game.<br><span>They recognise what is about to happen.</span></p><div id="intro"><button class="btn" id="startSetup">START POSITION TRAINING&nbsp; →</button></div><div id="setup" class="setup-panel hidden"><div class="eyebrow">Player profile</div><div class="setup-grid"><div class="field"><label>Primary position</label><strong>Left Wing</strong></div><div class="field"><label>Preferred foot</label><strong>Right</strong></div><div class="field"><label>Secondary position</label><strong>CAM</strong></div><div class="field"><label>Experience</label><strong>Advanced / Competitive</strong></div></div><button class="btn" id="launchLesson">LAUNCH LESSON 1&nbsp; →</button></div></section></main>`;document.querySelector('#startSetup').onclick=()=>{document.querySelector('#intro').classList.add('hidden');document.querySelector('#setup').classList.remove('hidden')};document.querySelector('#launchLesson').onclick=()=>{state.onboarded=true;saveProgress();currentView='lesson';render()}}

const navItems=[['dashboard','▦','Overview'],['course','◫','LW Course'],['match','▶','Match IQ'],['board','↗','Tactical Board'],['daily','◷','10 Min Session'],['cam','◇','CAM Academy']];
function shell(content,title){return `<div class="layout"><aside class="sidebar"><div class="brand"><span class="brand-mark">W</span><span>WINGER IQ</span></div><nav class="nav">${navItems.map(([id,icon,label])=>`<button class="nav-btn ${currentView===id||(currentView==='lesson'&&id==='course')?'active':''} ${id==='cam'&&overall()<45?'locked':''}" data-view="${id}"><b>${icon}</b><span>${label}</span></button>`).join('')}</nav><div class="profile-chip"><strong>${rank()}</strong><small>Right-footed LW</small></div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">${currentView==='dashboard'?'Performance centre':'Training ground'}</div><h1>${title}</h1></div><div class="streak"><strong>${state.streak}</strong> day streak</div></header>${content}</main></div>`}
function bindNav(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(b.dataset.view==='cam'&&overall()<45){toast('Build Winger IQ to 45 to unlock CAM Academy');return}dailySession=null;currentView=b.dataset.view;render()})}
function skillLabel(k){return ({positioning:'Positioning',scanning:'Scanning',movement:'Off-ball movement',onevone:'1v1 decisions',combination:'Combination play',finalThird:'Final-third decisions',pressing:'Pressing',transition:'Transition IQ'})[k]}
function dashboard(){const score=overall(),done=completedCount();const content=`<section class="grid dashboard-grid"><div><article class="card iq-card"><div class="iq-ring" style="--score:${score}"><div><b>${score}</b><small>Winger IQ</small></div></div><div><div class="eyebrow">Overall profile</div><h2 style="margin:7px 0 20px">${rank()}</h2><div class="skill-list">${Object.entries(state.scores).map(([k,v])=>`<div class="skill-row"><span>${skillLabel(k)} · ${v}</span><div class="bar"><i style="width:${v}%"></i></div></div>`).join('')}</div></div></article><div class="grid paths"><article class="card path primary"><span class="tag">PRIMARY POSITION</span><h2 style="margin-top:13px">LEFT WINGER</h2><p>Exploit the fullback. Arrive with a decision.</p><button class="btn" data-action="lesson">${done?'CONTINUE TRAINING':'START LESSON 1'}</button><span class="path-number">11</span></article><article class="card path"><span class="tag">${score>=45?'UNLOCKED':'LOCKED · IQ 45'}</span><h2 style="margin-top:13px">CAM ACADEMY</h2><p>Manipulate the lines. Connect the attack.</p><button class="btn secondary" data-view="cam">${score>=45?'ENTER ACADEMY':'BUILD FUNDAMENTALS'}</button><span class="path-number">10</span></article></div></div><div class="grid stat-grid"><article class="card stat"><span class="muted">Lessons complete</span><b>${done}/10</b></article><article class="card stat"><span class="muted">Quiz accuracy</span><b>${accuracy()}%</b></article><article class="card stat"><span class="muted">Scenario accuracy</span><b>${accuracy()}%</b></article><article class="card stat"><span class="muted">Match IQ best</span><b>${state.highestMatchIQ||'—'}</b></article><article class="card stat" style="grid-column:1/-1"><span class="muted">Next coaching focus</span><b style="font-size:1.15rem">Scan the right-back's hips before the pass travels.</b></article><button class="btn ghost danger" id="resetProgress" style="grid-column:1/-1">RESET PROGRESS</button></div></section>`;app.innerHTML=shell(content,'See the game before the ball arrives.');bindNav();document.querySelector('[data-action="lesson"]').onclick=()=>{currentView=done?nextTrainingView():'lesson';render()};document.querySelector('#resetProgress').onclick=e=>{if(e.currentTarget.dataset.ready==='yes'){state=structuredClone(baseProgress);localStorage.removeItem(STORAGE_KEY);currentView='welcome';render()}else{e.currentTarget.dataset.ready='yes';e.currentTarget.textContent='CONFIRM RESET — THIS DEVICE';toast('Press again to confirm reset')}}}

const scenario={prompt:'Your left-back has the ball. The opposition right-back has stepped tight. Space is open behind him.',answers:[['Drop toward the ball','You move into the pressure and shorten the pitch. The pass to feet is already denied.'],['Run behind','The right-back has stepped tight enough to deny your feet. His movement opens the space behind—attack it immediately.'],['Stay still','Stillness lets the defender control both you and the space. Make him turn.'],['Move centrally','The centre is occupied and this movement removes your team’s width.']]};
function pitchHTML(){return `<div class="pitch-wrap"><div class="pitch"><div class="box"></div><div class="box right"></div><div class="space-zone" id="spaceZone" style="left:16%;top:4%;width:17%;height:31%"></div><div class="player blue" style="left:18%;top:50%">LB</div><div class="player blue" style="left:40%;top:60%">CM</div><div class="player blue" style="left:57%;top:50%">CAM</div><div class="player blue" style="left:72%;top:50%">ST</div><div class="player you" id="you" style="left:29%;top:30%">YOU</div><div class="player red" id="rb" style="left:34%;top:30%">RB</div><div class="player red" style="left:74%;top:38%">CB</div><div class="player red" style="left:77%;top:62%">CB</div><div class="ball" style="left:20%;top:47%"></div></div></div>`}
function lesson(){const content=`<div class="lesson-progress"><i style="width:10%"></i></div><section class="lesson-shell"><article class="card pitch-card"><div class="pitch-head"><div><div class="eyebrow">Live tactical view</div><strong>Attacking left → right</strong></div><span class="tag">4–2–3–1</span></div>${pitchHTML()}</article><article class="card coach-panel"><div class="step">Lesson 01 · Positioning without the ball</div><h2>Recognise what the defender gives you.</h2><div class="principle"><span>WIDE → ISOLATE</span><span>INSIDE → COMBINE</span><span>BEHIND → THREATEN</span></div><p class="situation">${scenario.prompt}</p><div class="choices" id="choices">${scenario.answers.map((a,i)=>`<button class="choice" data-answer="${i}"><b>${String.fromCharCode(65+i)}</b>${a[0]}</button>`).join('')}</div><div id="feedback"></div></article></section>`;app.innerHTML=shell(content,'Positioning without the ball');bindNav();document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answerScenario(+b.dataset.answer))}
function answerScenario(index){if(document.querySelector('.choice.correct'))return;state.attempts++;state.scenarios++;const correct=index===1;if(correct){state.correct++;state.scores.positioning=Math.min(100,state.scores.positioning+5);state.scores.movement=Math.min(100,state.scores.movement+3)}else state.scores.positioning=Math.min(100,state.scores.positioning+1);saveProgress();const buttons=[...document.querySelectorAll('.choice')];buttons.forEach(b=>b.disabled=true);buttons[index].classList.add(correct?'correct':'wrong');buttons[1].classList.add('correct');document.querySelector('#spaceZone').classList.add('show');document.querySelector('#rb').style.left='29%';setTimeout(()=>{document.querySelector('#you').style.left='18%';document.querySelector('#you').style.top='13%'},350);document.querySelector('#feedback').innerHTML=`<div class="feedback"><strong>${correct?'CORRECT — ELITE DECISION':'BETTER OPTION — RUN BEHIND'}</strong><p>${scenario.answers[index][1]}</p>${!correct?`<p><b>What a high-level winger sees:</b> ${scenario.answers[1][1]}</p>`:''}<div class="completion-actions"><button class="btn" id="nextModule">CONTINUE: POSITIONING EXERCISE →</button><button class="btn ghost" id="lessonCourse">VIEW COURSE</button></div></div>`;document.querySelector('#nextModule').onclick=()=>{currentView='train:positioning';render()};document.querySelector('#lessonCourse').onclick=()=>{currentView='course';render()}}
const modules=[
  ['Positioning foundations','Width, half-space, blind-side and timing.','positioning',['Drag position','Decision']],
  ['Receiving the ball','Shape the first touch before pressure arrives.','receiving',['Touch direction','Body shape']],
  ['Scanning','Build the picture before the ball travels.','scanning',['Timed scan','Recall']],
  ['1v1 decisions','Exploit balance, space and support—not tricks.','duel',['Defender read','Tempo']],
  ['Off-ball movement','Use double movements and blind-side runs.','movement',['Animation lab','Run test']],
  ['Combinations','Connect with LB, CAM and striker.','combinations',['Next pass','Patterns']],
  ['Final third','Choose the action the picture demands.','final',['Box decisions','Delivery']],
  ['Pressing','Curve the run. Remove the next pass.','pressing',['Press angle','Cover shadow']],
  ['Transitions','Recognise the first three seconds.','transition',['Rapid fire','Recovery']],
  ['Advanced winger IQ','Read and adapt to the fullback.','defender',['Opponent profile','Adaptation']]
];
const moduleOrder=modules.map(m=>m[2]);
function completedCount(){return new Set(state.completedModules||[]).size}
function isComplete(type){return (state.completedModules||[]).includes(type)}
function completeModule(type){if(!moduleOrder.includes(type)||isComplete(type))return;state.completedModules=[...(state.completedModules||[]),type];state.completedLessons=completedCount();saveProgress()}
function nextTrainingView(){const next=moduleOrder.find(type=>!isComplete(type));return next?'train:'+next:'course'}
function completionActions(type){if(dailySession){const final=dailySession.index>=dailySession.queue.length-1;return `<div class="completion-actions"><button class="btn" data-daily-next>${final?'FINISH SESSION →':`CONTINUE: DRILL ${dailySession.index+2} →`}</button><button class="btn ghost" data-exit-session>EXIT SESSION</button></div>`}const index=moduleOrder.indexOf(type),next=moduleOrder[index+1];return `<div class="completion-actions"><button class="btn" data-continue-module="${next||'dashboard'}">${next?`CONTINUE: ${modules[index+1][0].toUpperCase()} →`:'FINISH COURSE →'}</button><button class="btn ghost" data-back-course>VIEW COURSE</button></div>`}
function bindCompletionActions(type){completeModule(type);if(dailySession){document.querySelector('[data-daily-next]')?.addEventListener('click',()=>{dailySession.index++;if(dailySession.index>=dailySession.queue.length){currentView='daily-summary';render()}else{currentView='train:'+dailySession.queue[dailySession.index];render()}});document.querySelector('[data-exit-session]')?.addEventListener('click',()=>{dailySession=null;currentView='daily';render()});return}document.querySelector('[data-continue-module]')?.addEventListener('click',e=>{const next=e.currentTarget.dataset.continueModule;currentView=next==='dashboard'?'dashboard':'train:'+next;render()});document.querySelector('[data-back-course]')?.addEventListener('click',()=>{currentView='course';render()})}
function lockAnswers(selector){document.querySelectorAll(selector).forEach(b=>b.disabled=true)}
function course(){const next=moduleOrder.find(type=>!isComplete(type));const content=`<div class="section-head"><div><div class="eyebrow">Left winger pathway</div><h2 style="margin:7px 0 0">Master the fullback duel.</h2></div><p>Built for a right-footed left winger: inside threat, outside credibility, and decisions made before receiving.</p></div><section class="grid module-grid">${modules.map((m,i)=>{const done=isComplete(m[2]);return `<article class="card module-card ${done?'done':''}"><span class="num">LEVEL ${String(i+1).padStart(2,'0')}</span><div class="eyebrow">${done?'Complete':'Tactical module'}</div><h3>${m[0]}</h3><p>${m[1]}</p><div class="skill-tags">${m[3].map(t=>`<span class="mini-tag">${t}</span>`).join('')}</div><button class="btn ${m[2]===next?'':'secondary'}" data-module="${m[2]}">${done?'REVIEW':m[2]===next?'CONTINUE':'TRAIN'}</button></article>`}).join('')}</section><article class="card" style="margin-top:16px"><div class="eyebrow">Play faster, think earlier</div><h2 style="margin:8px 0">SCAN → DECIDE → RECEIVE → EXECUTE</h2><p class="muted">The decision is not faster after the ball arrives. Most of it is already made.</p><button class="btn secondary" data-module="predecision">PRE-RECEIVE CHALLENGE</button></article>`;app.innerHTML=shell(content,'Left Winger Course');bindNav();document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{currentView='train:'+b.dataset.module;render()})}

const movementData={movement:[['Run behind','Pin high, then attack the space behind the right-back.'],['Check short → spin','Sell the pass to feet; leave on the defender’s first step.'],['Wide → inside','Start outside his eyeline, finish in the half-space.'],['Far-post run','Arrive beyond the far centre-back as the crosser looks up.']],defender:[['RB marks tight','Threaten behind immediately. Make him turn.'],['RB drops','Receive to feet, build speed and attack his front foot.'],['RB tucks inside','Hold width. Stretch the line before the next action.'],['RB shows outside','Use the line threat; fake it and attack inside if the lane opens.']]};
const pitchLayouts={
  empty:{players:[],ball:[50,50]},
  base:{players:[['blue','LB',22,57],['blue','CAM',49,58],['blue','ST',72,46],['you','YOU',28,27,'activeYou'],['red','RB',38,28,'activeRB'],['red','CB',76,39]],ball:[22,55]},
  positioning:{players:[['blue','LB',23,58],['blue','RCM',43,58],['blue','CAM',58,47],['blue','ST',76,48],['you','YOU',30,28,'activeYou'],['red','RB',43,34,'activeRB'],['red','CB',76,39],['red','CM',55,60]],ball:[43,57],cues:'<div class="cue-zone open" style="left:14%;top:5%;width:21%;height:28%"><span>WIDTH</span></div>'},
  receiving:{players:[['blue','LB',25,56],['blue','CAM',55,55],['blue','ST',78,47],['you','YOU',43,25,'activeYou'],['red','RB',49,34,'activeRB'],['red','CB',78,38]],ball:[35,40],cues:'<div class="cue-zone open" style="left:35%;top:4%;width:22%;height:27%"><span>LINE OPEN</span></div><i class="cue-line pass" style="left:27%;top:53%;width:19%;transform:rotate(-39deg)"></i>'},
  scanning:{players:[['blue','LB',25,59],['blue','CAM',56,53],['blue','ST',78,47],['you','YOU',42,22,'activeYou'],['red','RB',49,30,'activeRB'],['red','CB',78,39],['red','CM',59,65]],ball:[28,56],cues:'<div class="cue-zone open" style="left:31%;top:3%;width:22%;height:25%"><span>OUTSIDE</span></div>'},
  duel:{players:[['blue','LB',34,57],['blue','CAM',60,57],['blue','ST',82,48],['you','YOU',57,24,'activeYou'],['red','RB',66,28,'activeRB',-28],['red','CB',84,40]],ball:[57,24],cues:'<div class="cue-zone target" style="left:62%;top:34%;width:18%;height:24%"><span>INSIDE LANE</span></div>'},
  movement:{players:[['blue','LB',27,57],['blue','CAM',54,55],['blue','ST',78,47],['you','YOU',34,24,'activeYou'],['red','RB',45,27,'activeRB'],['red','CB',77,38]],ball:[30,55],cues:'<i class="cue-line run" style="left:35%;top:24%;width:24%;transform:rotate(-20deg)"></i>'},
  defender:{players:[['blue','LB',26,58],['blue','CAM',58,56],['blue','ST',80,48],['you','YOU',42,24,'activeYou'],['red','RB',48,27,'activeRB',180],['red','CB',79,39]],ball:[29,55],cues:'<div class="cue-zone open" style="left:36%;top:3%;width:20%;height:24%"><span>BEHIND</span></div>'},
  combinations:{players:[['blue','LB',42,56],['blue','CAM',65,47],['blue','ST',83,51],['you','YOU',69,22,'activeYou'],['red','RB',66,29,'activeRB'],['red','CB',82,43],['red','CB',84,61]],ball:[65,47],cues:'<i class="cue-line pass" style="left:65%;top:46%;width:18%;transform:rotate(-55deg)"></i><div class="cue-zone target" style="left:68%;top:5%;width:18%;height:23%"><span>RETURN LANE</span></div>'},
  final:{players:[['blue','LB',70,13],['blue','CAM',76,56],['blue','ST',88,42],['you','YOU',78,26,'activeYou'],['red','RB',83,31,'activeRB'],['red','CB',89,51],['red','CB',90,67]],ball:[78,26],cues:'<i class="cue-line run" style="left:69%;top:14%;width:19%;transform:rotate(5deg)"></i><div class="cue-zone target" style="left:82%;top:9%;width:15%;height:22%"><span>OVERLAP</span></div>'},
  pressing:{players:[['blue','CM',51,57],['blue','ST',78,53],['you','YOU',55,29,'activeYou'],['red','RB',61,12,'activeRB'],['red','CB',74,29],['red','CB',78,62],['red','CM',55,67]],ball:[74,29],cues:'<i class="cue-line danger-line" style="left:62%;top:15%;width:17%;transform:rotate(37deg)"></i><div class="cue-zone target" style="left:58%;top:8%;width:18%;height:24%"><span>BLOCK LANE</span></div>'},
  transition:{players:[['blue','CM',48,54],['blue','CAM',61,57],['blue','ST',81,49],['you','YOU',60,16,'activeYou'],['red','RB',45,20,'activeRB'],['red','CB',72,35,0,180],['red','CB',75,60]],ball:[48,54],cues:'<div class="cue-zone open" style="left:55%;top:3%;width:25%;height:24%"><span>BLIND SIDE</span></div><i class="cue-line run" style="left:59%;top:18%;width:22%;transform:rotate(-8deg)"></i>'},
  predecision:{players:[['blue','LB',31,57],['blue','CAM',58,56],['blue','ST',80,48],['you','YOU',48,24,'activeYou'],['red','RB',54,31,'activeRB'],['red','CB',80,39]],ball:[37,43],cues:'<i class="cue-line pass" style="left:36%;top:43%;width:17%;transform:rotate(-31deg)"></i><div class="cue-zone open" style="left:39%;top:3%;width:20%;height:25%"><span>DECIDE NOW</span></div>'}
};
function genericPitch(extra='',variant='base'){const layout=pitchLayouts[variant]||pitchLayouts.base;const players=layout.players.map(([team,label,x,y,id,facing])=>`<div class="player ${team}" ${id?`id="${id}"`:''} style="left:${x}%;top:${y}%">${label}${Number.isFinite(facing)?`<i class="facing" style="transform:rotate(${facing}deg)"></i>`:''}</div>`).join('');return `<div class="pitch-wrap" data-layout="${variant}"><div class="pitch tactical-board" id="activePitch"><div class="box"></div><div class="box right"></div>${extra}${layout.cues||''}${players}<div class="ball" id="activeBall" style="left:${layout.ball[0]}%;top:${layout.ball[1]}%"></div></div></div>`}
function train(type){if(type==='positioning')return positioningExercise();if(type==='receiving')return receivingExercise();if(type==='scanning')return scanChallenge();if(['movement','defender'].includes(type))return movementLab(type);if(type==='combinations')return combinationGame();if(type==='final')return decisionGame('final');if(type==='pressing')return pressingGame();if(type==='transition')return decisionGame('transition');if(type==='duel')return decisionGame('duel');if(type==='predecision')return preDecision();return course()}
function trainingFrame(title,kicker,pitch,aside){app.innerHTML=shell(`<section class="training-layout"><article class="card pitch-card"><div class="pitch-head"><div><div class="eyebrow">${kicker}</div><strong>Read the live picture</strong></div><span class="tag">ATTACK →</span></div>${pitch}</article><article class="card coach-panel">${aside}</article></section>`,title);bindNav()}

function positioningExercise(){const zones=`<div class="zone green" style="left:15%;top:5%;width:19%;height:28%"></div><div class="zone yellow" style="left:29%;top:8%;width:22%;height:36%"></div><div class="zone red" style="left:47%;top:4%;width:30%;height:55%"></div>`;trainingFrame('Drag positioning','Level 01 · Positioning',genericPitch(zones,'positioning'),`<div class="step">Narrow opposition block</div><h2>Where do you give the attack its next advantage?</h2><p class="situation">Your RCM has the ball. Their right-back is tucked inside and the block is narrow. Drag YOU into your best position.</p><button class="btn" id="submitDrag">SUBMIT POSITION</button><div id="feedback"></div>`);const you=document.querySelector('#activeYou'),pitch=document.querySelector('#activePitch'),submit=document.querySelector('#submitDrag');makeDraggable(you,pitch);submit.onclick=()=>{submit.disabled=true;const x=parseFloat(you.style.left),y=parseFloat(you.style.top);const good=x<35&&y<38;record('positioning',good,good?5:1);document.querySelector('#feedback').innerHTML=`<div class="feedback"><strong>${good?'EXCELLENT ZONE':'REASSESS THE WIDTH'}</strong><p>${good?'Hold the touchline. The tucked-in right-back must choose: stay narrow and concede the switch, or jump wide and open the channel.':'You have joined the narrow block. Stay outside the right-back first—force him to reveal his decision.'}</p>${completionActions('positioning')}</div>`;bindCompletionActions('positioning')}}
function makeDraggable(el,container){let drag=false;const move=e=>{if(!drag)return;const r=container.getBoundingClientRect(),p=e.touches?e.touches[0]:e;el.style.left=Math.max(3,Math.min(97,(p.clientX-r.left)/r.width*100))+'%';el.style.top=Math.max(4,Math.min(96,(p.clientY-r.top)/r.height*100))+'%'};el.onpointerdown=e=>{drag=true;el.setPointerCapture(e.pointerId)};el.onpointermove=move;el.onpointerup=()=>drag=false;el.addEventListener('touchmove',move,{passive:false})}

function receivingExercise(){trainingFrame('Receive to eliminate pressure','Level 02 · First touch',genericPitch('','receiving'),`<div class="step">Defender approaching inside</div><h2>Choose your first-touch direction.</h2><p class="situation">The right-back is arriving from your inside shoulder. The line is open and your hips are half-open.</p><div class="direction-pad"><button data-dir="inside" aria-label="Touch inside" style="grid-column:1;grid-row:2">←</button><button data-dir="forward" aria-label="Touch forward" style="grid-column:2;grid-row:1">↑</button><div class="center">YOU</div><button data-dir="line" aria-label="Touch down the line" style="grid-column:3;grid-row:2">→</button><button data-dir="set" aria-label="Set backward" style="grid-column:2;grid-row:3">↓</button></div><div id="feedback"></div>`);document.querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>{lockAnswers('[data-dir]');const good=b.dataset.dir==='line';record('movement',good,good?4:1);const you=document.querySelector('#activeYou');you.style.left=good?'54%':b.dataset.dir==='inside'?'58%':'45%';you.style.top=good?'13%':'38%';document.querySelector('#activeRB').style.left=good?'48%':'51%';document.querySelector('#feedback').innerHTML=`<div class="feedback"><strong>${good?'PRESSURE ELIMINATED':'PRESSURE INVITED'}</strong><p>${good?'Touch down the line with the outside picture already scanned. The defender cannot reach across your body.':'That touch carries you toward the defender’s pressure. The high-level action uses body shape to take the defender out with touch one.'}</p>${completionActions('receiving')}</div>`;bindCompletionActions('receiving')})}

function scanChallenge(){trainingFrame('Scan Challenge','Level 03 · Scanning',genericPitch('','scanning'),`<div class="step">Intermediate · 2.5 seconds</div><h2>Build the picture. It will disappear.</h2><p class="situation" id="scanPrompt">Scan: defender, space, teammates, next action.</p><button class="btn" id="startScan">START SCAN</button><div id="scanAnswers" class="choices hidden"><button class="choice" data-scan="inside"><b>A</b>Space was inside</button><button class="choice" data-scan="outside"><b>B</b>Space was outside</button><button class="choice" data-scan="none"><b>C</b>No forward space</button></div><div id="feedback"></div>`);const wrap=document.querySelector('.pitch-wrap');wrap.insertAdjacentHTML('beforeend','<div class="scan-overlay" id="scanCover">PICTURE HIDDEN</div>');document.querySelector('#startScan').onclick=()=>{document.querySelector('#startScan').disabled=true;document.querySelector('#scanPrompt').innerHTML='<span class="timer">2.5</span> seconds';setTimeout(()=>{const cover=document.querySelector('#scanCover');if(!cover)return;cover.classList.add('cover');document.querySelector('#scanAnswers').classList.remove('hidden')},2500)};document.querySelectorAll('[data-scan]').forEach(b=>b.onclick=()=>{lockAnswers('[data-scan]');const good=b.dataset.scan==='outside';record('scanning',good,good?5:1);document.querySelector('#feedback').innerHTML=`<div class="feedback"><strong>${good?'PICTURE RETAINED':'SCAN MISSED'}</strong><p>${good?'The RB was inside of you; the outside lane was open. Your first touch can eliminate him.':'The key cue was the defender’s inside position. Space was available outside, toward the line.'}</p>${completionActions('scanning')}</div>`;bindCompletionActions('scanning')})}

function movementLab(type){const items=movementData[type];trainingFrame(type==='movement'?'Movement animation lab':'Read the defender',type==='movement'?'Level 05 · Off-ball':'Level 10 · Adaptation',genericPitch('',type),`<div class="step">${type==='movement'?'Movement library':'Right-back behaviour'}</div><h2 id="labTitle">${items[0][0]}</h2><p class="situation" id="labText">${items[0][1]}</p><div class="choices">${items.map((m,i)=>`<button class="choice" data-move="${i}"><b>${i+1}</b>${m[0]}</button>`).join('')}</div><div id="feedback"></div>`);const play=i=>{document.querySelector('#labTitle').textContent=items[i][0];document.querySelector('#labText').textContent=items[i][1];const y=document.querySelector('#activeYou'),rb=document.querySelector('#activeRB');if(type==='movement'){y.style.left='34%';y.style.top='24%';rb.style.left='45%';rb.style.top='27%'}else{const rbStates=[[48,27],[58,33],[57,42],[53,26]][i];y.style.left='42%';y.style.top='24%';rb.style.left=rbStates[0]+'%';rb.style.top=rbStates[1]+'%'}setTimeout(()=>{if(type==='movement'){const targets=[[57,8],[47,13],[57,35],[88,70]][i];y.style.left=targets[0]+'%';y.style.top=targets[1]+'%'}else{const targets=[[58,9],[50,24],[37,20],[61,35]][i];y.style.left=targets[0]+'%';y.style.top=targets[1]+'%' }},180);document.querySelector('#feedback').innerHTML=`<div class="feedback"><strong>PATTERN REPLAYED</strong><p>${items[i][1]}</p>${completionActions(type)}</div>`;bindCompletionActions(type)};document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>play(+b.dataset.move))}

function combinationGame(){trainingFrame('Predict the next pass','Level 06 · Combinations',genericPitch('','combinations'),`<div class="step">LW + CAM + ST</div><h2>Who receives next?</h2><p class="situation">You bounced the ball into CAM and spun behind the right-back. The striker pins the near centre-back.</p><div class="choices"><button class="choice" data-next="lw"><b>A</b>Return into LW run</button><button class="choice" data-next="st"><b>B</b>Force pass into striker</button><button class="choice" data-next="lb"><b>C</b>Reset to left-back</button></div><div id="feedback"></div>`);document.querySelectorAll('[data-next]').forEach(b=>b.onclick=()=>{lockAnswers('[data-next]');const good=b.dataset.next==='lw';record('combination',good,good?5:1);if(good){document.querySelector('#activeBall').style.left='75%';document.querySelector('#activeBall').style.top='17%';document.querySelector('#activeYou').style.left='75%';document.querySelector('#activeYou').style.top='15%'}document.querySelector('#feedback').innerHTML=`<div class="feedback"><strong>${good?'THIRD-MAN PATTERN COMPLETE':'THE WINDOW CLOSES'}</strong><p>${good?'CAM sets the angle; your spin attacks the gap. The return pass eliminates two defenders.':'The bounce created a third-man lane behind the fullback. Use it before the line resets.'}</p>${completionActions('combinations')}</div>`;bindCompletionActions('combinations')})}

const decisions={final:{pitch:'final',title:'What is the best final-third action?',situation:'You receive at the left edge of the box. ST attacks near post, CAM arrives at the cutback zone, RB blocks inside, and LB overlaps.',answers:[['Force inside shot',false],['Release the overlapping LB',true],['Early high cross',false],['Reset immediately',false]],why:'The overlap moves the ball beyond the blocker. Continue into the box for the return or far-post second action.',skill:'finalThird'},transition:{pitch:'transition',title:'Possession won. Your first action?',situation:'CM wins it centrally. Their RB is high; the nearest CB is looking at the ball. You are outside his blind side.',answers:[['Come short slowly',false],['Sprint into blind-side space',true],['Hold behind the ball',false],['Move into the crowded centre',false]],why:'Attack the blind side before the defensive line can turn and organise.',skill:'transition'},duel:{pitch:'duel',title:'What do you attack?',situation:'The RB is angled toward the touchline with his weight heavy on the outside leg.',answers:[['His outside shoulder',false],['His front foot, then inside',true],['A standing skill move',false],['The pass backward',false]],why:'Attack the loaded front foot. The change of direction forces a slow weight transfer and opens the inside lane.',skill:'onevone'}};
function decisionGame(type){const d=decisions[type];trainingFrame(d.title,type==='duel'?'Level 04 · 1v1':type==='final'?'Level 07 · Final third':'Level 09 · Transition',genericPitch('',d.pitch),`<div class="step">Live decision</div><h2>${d.title}</h2><p class="situation">${d.situation}</p><div class="choices">${d.answers.map((a,i)=>`<button class="choice" data-decision="${i}"><b>${String.fromCharCode(65+i)}</b>${a[0]}</button>`).join('')}</div><div id="feedback"></div>`);document.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>{lockAnswers('[data-decision]');const good=d.answers[+b.dataset.decision][1];record(d.skill,good,good?5:1);b.classList.add(good?'correct':'wrong');const correctIndex=d.answers.findIndex(a=>a[1]);document.querySelectorAll('[data-decision]')[correctIndex].classList.add('correct');document.querySelector('#feedback').innerHTML=`<div class="feedback"><strong>${good?'HIGH-LEVEL READ':'THE PICTURE OFFERED MORE'}</strong><p>${d.why}</p>${completionActions(type)}</div>`;bindCompletionActions(type)})}

function pressingGame(){trainingFrame('Curve the press','Level 08 · Pressing',genericPitch('','pressing'),`<div class="step">Back-pass trigger</div><h2>Choose your pressing angle.</h2><p class="situation">Their centre-back receives a back-pass near the right side. Your job is to press while removing the easy return to right-back.</p><div class="choices"><button class="choice" data-press="straight"><b>A</b>Straight at the ball</button><button class="choice" data-press="curve"><b>B</b>Curve outside → in</button><button class="choice" data-press="hold"><b>C</b>Hold your position</button></div><div id="feedback"></div>`);document.querySelectorAll('[data-press]').forEach(b=>b.onclick=()=>{lockAnswers('[data-press]');const good=b.dataset.press==='curve';record('pressing',good,good?5:1);const y=document.querySelector('#activeYou');y.style.left=good?'66%':'58%';y.style.top=good?'28%':'40%';document.querySelector('#feedback').innerHTML=`<div class="feedback"><strong>${good?'PASSING LANE REMOVED':'LANE LEFT OPEN'}</strong><p>${good?'The curve puts the right-back in your cover shadow and guides play toward central pressure.':'A straight run is fast but incomplete: the easy outlet stays available.'}</p>${completionActions('pressing')}</div>`;bindCompletionActions('pressing')})}

function preDecision(){trainingFrame('Play faster, think earlier','Pre-receive challenge',genericPitch('','predecision'),`<div class="step">Ball arrives in <span id="preTimer">1.5</span>s</div><h2>Decide before the pass reaches you.</h2><p class="situation">RB is tight inside. LB is supporting underneath. The outside channel is open.</p><div class="choices">${['Turn inside','Set the LB','Drive down the line','Bounce to CAM'].map((x,i)=>`<button class="choice" data-pre="${i}"><b>${i+1}</b>${x}</button>`).join('')}</div><div id="feedback"></div>`);let time=1.5,closed=false;const tick=setInterval(()=>{time-=.1;const el=document.querySelector('#preTimer');if(!el){clearInterval(tick);return}el.textContent=Math.max(0,time).toFixed(1);if(time<=0){closed=true;clearInterval(tick);lockAnswers('[data-pre]');document.querySelector('#feedback').innerHTML='<div class="feedback"><strong>WINDOW CLOSED</strong><p>Your next rep begins with an earlier scan.</p><div class="completion-actions"><button class="btn" id="retryPre">TRY AGAIN</button><button class="btn ghost" id="backPre">VIEW COURSE</button></div></div>';document.querySelector('#retryPre').onclick=()=>preDecision();document.querySelector('#backPre').onclick=()=>{currentView='course';render()}}},100);document.querySelectorAll('[data-pre]').forEach(b=>b.onclick=()=>{if(closed)return;clearInterval(tick);lockAnswers('[data-pre]');const good=+b.dataset.pre===2;record('scanning',good,good?4:1);document.querySelector('#feedback').innerHTML=`<div class="feedback"><strong>${good?'DECISION LOCKED EARLY':'RE-SCAN THE OUTSIDE'}</strong><p>${good?'Open touch down the line. You chose it while the ball travelled.':'The free channel was outside; decide from the scan, then execute on arrival.'}</p><div class="completion-actions"><button class="btn" id="retryPre">ANOTHER REP</button><button class="btn ghost" id="backPre">VIEW COURSE</button></div></div>`;document.querySelector('#retryPre').onclick=()=>preDecision();document.querySelector('#backPre').onclick=()=>{currentView='course';render()}})}

function record(skill,good,points){state.attempts++;state.scenarios++;if(good)state.correct++;if(dailySession)dailySession.results.push(good);state.scores[skill]=Math.min(100,state.scores[skill]+points);saveProgress()}

const matchRounds=[decisions.transition,decisions.duel,decisions.final,{pitch:'pressing',title:'The ball is lost. Your first job?',situation:'Their RB is already moving beyond you while the ball is central.',answers:[['Appeal for a foul',false],['Track the RB and protect the lane',true],['Stay high for the counter',false]],why:'Remove the immediate overload, then recover your attacking position.',skill:'pressing'}];
let matchState={round:0,points:0,answers:[]};
function matchIQ(){matchState={round:0,points:0,answers:[]};renderMatchRound()}
function renderMatchRound(){if(matchState.round>=matchRounds.length)return matchResult();const d=matchRounds[matchState.round];const content=`<div class="match-hud"><span class="tag">MATCH MINUTE ${18+matchState.round*17}</span><div>IQ POINTS <b class="countdown">${matchState.points}</b></div></div><section class="training-layout"><article class="card pitch-card">${genericPitch('',d.pitch||'base')}</article><article class="card coach-panel"><div class="step">Situation ${matchState.round+1}/${matchRounds.length}</div><h2>${d.title}</h2><p class="situation">${d.situation}</p><div class="choices">${d.answers.map((a,i)=>`<button class="choice" data-match="${i}"><b>${String.fromCharCode(65+i)}</b>${a[0]}</button>`).join('')}</div></article></section>`;app.innerHTML=shell(content,'MATCH IQ');bindNav();document.querySelectorAll('[data-match]').forEach(b=>b.onclick=()=>{lockAnswers('[data-match]');const good=d.answers[+b.dataset.match][1];const pts=good?100:30;matchState.points+=pts;matchState.answers.push(good);record(d.skill,good,good?3:1);b.classList.add(good?'correct':'wrong');setTimeout(()=>{matchState.round++;renderMatchRound()},650)})}
function matchResult(){const score=Math.round(matchState.points/matchRounds.length);state.highestMatchIQ=Math.max(state.highestMatchIQ,score);saveProgress();const weak=Object.entries(state.scores).sort((a,b)=>a[1]-b[1]).slice(0,3);app.innerHTML=shell(`<article class="card"><div class="eyebrow">Full time · Decision report</div><div class="score-flash">${score}</div><h2>WINGER IQ SCORE</h2><div class="grid skill-list" style="margin:25px 0">${Object.entries(state.scores).slice(0,6).map(([k,v])=>`<div class="skill-row"><span>${skillLabel(k)} · ${v}</span><div class="bar"><i style="width:${v}%"></i></div></div>`).join('')}</div><div class="feedback"><strong>NEXT TRAINING FOCUS</strong><p>${weak.map(x=>skillLabel(x[0])).join(' · ')}</p></div><button class="btn" style="margin-top:16px" data-view="course">TRAIN WEAK AREAS</button></article>`,'Match report');bindNav()}

const formations={'4-2-3-1':[[20,52,'LB'],[38,42,'CM'],[48,65,'CM'],[56,50,'CAM'],[70,48,'ST'],[28,22,'YOU'],[16,74,'RB']], '4-3-3':[[20,52,'LB'],[40,38,'CM'],[45,66,'CM'],[57,52,'CM'],[73,49,'ST'],[30,20,'YOU'],[20,79,'RW']], '4-4-2':[[20,52,'LB'],[38,35,'LM'],[43,65,'CM'],[68,40,'ST'],[70,62,'ST'],[29,18,'YOU'],[21,80,'RM']], '3-4-2-1':[[24,50,'CB'],[41,34,'CM'],[43,68,'CM'],[58,36,'10'],[58,64,'10'],[75,50,'ST'],[30,18,'YOU']]};
function tacticalBoard(){const players=formations['4-2-3-1'].map((p,i)=>`<div class="player ${p[2]==='YOU'?'you':'blue'} board-player" style="left:${p[0]}%;top:${p[1]}%">${p[2]}</div>`).join('')+[['RB',38,23],['CB',72,40],['CB',73,60],['CM',50,72]].map(p=>`<div class="player red board-player" style="left:${p[1]}%;top:${p[2]}%">${p[0]}</div>`).join('');const content=`<div class="board-tools"><select class="tool-btn" id="formation">${Object.keys(formations).map(f=>`<option>${f}</option>`).join('')}</select><button class="tool-btn active" id="drawMove">Draw movement</button><button class="tool-btn" id="drawPass">Draw pass</button><button class="tool-btn" id="addPlayer">+ Player</button><button class="tool-btn" id="removePlayer">− Player</button><button class="tool-btn" id="resetBoard">Reset</button></div><section class="training-layout"><article class="card pitch-card">${genericPitch(players,'empty')}</article><article class="card"><div class="eyebrow">Tactical free play</div><h2 style="margin:8px 0">Move the picture.</h2><p class="situation">Drag every player and the ball. Drag on open space to draw a run or passing line.</p><div class="principle"><span>MOVE</span><span>PASS</span><span>ROTATE</span></div></article></section>`;app.innerHTML=shell(content,'Tactical Board');bindNav();setupBoard()}
function setupBoard(){const pitch=document.querySelector('#activePitch'),moveBtn=document.querySelector('#drawMove'),passBtn=document.querySelector('#drawPass');pitch.querySelectorAll('.board-player,.ball').forEach(p=>makeDraggable(p,pitch));let start=null,mode='move';pitch.onpointerdown=e=>{if(e.target!==pitch)return;const r=pitch.getBoundingClientRect();start={x:e.clientX-r.left,y:e.clientY-r.top}};pitch.onpointerup=e=>{if(!start||e.target!==pitch)return;const r=pitch.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,dx=x-start.x,dy=y-start.y;if(Math.hypot(dx,dy)<12){start=null;return}const line=document.createElement('i'),color=mode==='pass'?'white':'var(--accent)';line.className='board-arrow';line.style.left=start.x+'px';line.style.top=start.y+'px';line.style.width=Math.hypot(dx,dy)+'px';line.style.transform=`rotate(${Math.atan2(dy,dx)}rad)`;line.style.setProperty('--arrow-color',color);pitch.append(line);start=null};const setMode=next=>{mode=next;moveBtn.classList.toggle('active',mode==='move');passBtn.classList.toggle('active',mode==='pass')};moveBtn.onclick=()=>setMode('move');passBtn.onclick=()=>setMode('pass');document.querySelector('#formation').onchange=e=>applyFormation(e.target.value);document.querySelector('#resetBoard').onclick=()=>tacticalBoard();document.querySelector('#addPlayer').onclick=()=>{const p=document.createElement('div');p.className='player blue board-player';p.textContent='P';p.style.left='50%';p.style.top='50%';pitch.append(p);makeDraggable(p,pitch)};document.querySelector('#removePlayer').onclick=()=>{const target=[...pitch.querySelectorAll('.board-player')].pop();if(target)target.remove();else toast('No player left to remove')}}
function applyFormation(name){const pitch=document.querySelector('#activePitch');pitch.querySelectorAll('.board-player.blue,.board-player.you').forEach(x=>x.remove());formations[name].forEach(p=>{const el=document.createElement('div');el.className=`player ${p[2]==='YOU'?'you':'blue'} board-player`;el.textContent=p[2];el.style.left=p[0]+'%';el.style.top=p[1]+'%';pitch.append(el);makeDraggable(el,pitch)})}

function daily(){const drills=[['Position','Hold width vs narrow block'],['Position','Attack behind a tight RB'],['Scan','Retain the defender picture'],['Scan','Find the free teammate'],['Decision','Choose first touch'],['Decision','Read body orientation'],['Press','Curve the press'],['Final third','Find the cutback']];const queue=['positioning','positioning','scanning','scanning','receiving','duel','pressing','final'];const content=`<section class="training-layout"><article class="card"><div class="eyebrow">Generated for today</div><h2 style="margin:8px 0 18px">10 Minute Position Session</h2><div class="session-stack">${drills.map((d,i)=>`<div class="session-item"><b>${i+1}</b><div><strong>${d[1]}</strong><div class="muted">${d[0]} · ${i<2?'90 sec':'60 sec'}</div></div></div>`).join('')}</div></article><article class="card coach-panel"><div class="step">Today’s coaching focus</div><h2>Hold width until the defender reacts.</h2><p class="situation">Do not move inside because the space looks attractive. First stretch the right-back; then exploit the space his decision creates.</p><button class="btn" id="startDaily">START SESSION</button><div id="dailyResult"></div></article></section>`;app.innerHTML=shell(content,"Today's Winger IQ");bindNav();document.querySelector('#startDaily').onclick=()=>{dailySession={index:0,queue,results:[]};currentView='train:'+queue[0];render()}}
function dailySummary(){const session=dailySession||{results:[]},correct=session.results.filter(Boolean).length,total=session.results.length,score=total?Math.round(correct/total*100):0;state.streak=Math.max(1,state.streak);saveProgress();const focus=score>=75?'Keep scanning early—your decisions stayed connected to the picture.':'Hold width longer and scan the fullback before the ball travels.';const content=`<article class="card"><div class="eyebrow">Session complete</div><div class="score-flash">${score}</div><h2>TODAY'S WINGER IQ</h2><p class="situation">${correct} of ${total} decisions matched the high-level action.</p><div class="feedback"><strong>COACHING FOCUS</strong><p>${focus}</p></div><div class="completion-actions"><button class="btn" id="finishDaily">RETURN TO OVERVIEW</button><button class="btn ghost" id="repeatDaily">REPEAT SESSION</button></div></article>`;app.innerHTML=shell(content,"10 Minute Session");bindNav();document.querySelector('#finishDaily').onclick=()=>{dailySession=null;currentView='dashboard';render()};document.querySelector('#repeatDaily').onclick=()=>{dailySession=null;currentView='daily';render()}}

function camAcademy(){const content=`<article class="card"><div class="eyebrow">Secondary pathway</div><h2 style="margin:8px 0">CAM ACADEMY</h2><p class="situation">SCAN → RECEIVE BETWEEN LINES → TURN OR CONNECT</p><div class="grid module-grid">${['Find space between lines','Play on the half-turn','Scan centrally','Receive under pressure','Create passing angles','Third-man combinations','Through balls','Tempo control','Position around striker','Arrive in the box','Counterpress','Break low blocks'].map((x,i)=>`<div class="module-card card"><span class="num">${String(i+1).padStart(2,'0')}</span><h3>${x}</h3><p>${i<6?'Manipulate midfield pressure and connect the next line.':'Advance after winger fundamentals are established.'}</p><span class="tag">${i<3?'AVAILABLE':'PROGRESSION'}</span></div>`).join('')}</div></article><article class="card" style="margin-top:16px"><div class="eyebrow">Position comparison</div><h2 style="margin:8px 0 18px">LW ↔ CAM</h2><div class="grid comparison"><div class="compare-side"><h3>LW sees</h3><ul><li>How do I exploit the fullback?</li><li>Can I isolate, combine or threaten behind?</li><li>Where is the weak-side finish?</li></ul></div><div class="compare-side"><h3>CAM sees</h3><ul><li>How do I manipulate both lines?</li><li>Can I turn, connect or become the third man?</li><li>Which defender can I draw out?</li></ul></div></div></article>`;app.innerHTML=shell(content,'Between the lines');bindNav()}

function registerWebMCP(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const safe=fn=>input=>Promise.resolve(fn(input));try{ctx.registerTool({name:'read_winger_iq_progress',title:'Read Winger IQ progress',description:'Read the current tactical training progress, overall score, rank, and topic ratings.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:safe(()=>({overall:overall(),rank:rank(),accuracy:accuracy(),scores:state.scores,scenarios:state.scenarios,completedModules:state.completedModules||[],nextModule:moduleOrder.find(type=>!isComplete(type))||null}))});ctx.registerTool({name:'start_winger_training_module',title:'Start training module',description:'Open one Winger IQ training module in the visible app.',inputSchema:{type:'object',properties:{module:{type:'string',enum:['positioning','receiving','scanning','duel','movement','combinations','final','pressing','transition','defender','predecision']}},required:['module'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:safe(input=>{if(!modules.some(m=>m[2]===input.module)&&input.module!=='predecision')throw new Error('Unknown module');currentView='train:'+input.module;render();return{opened:input.module}})});ctx.registerTool({name:'reset_winger_iq_progress',title:'Reset Winger IQ progress',description:'Erase all saved Winger IQ training progress on this device.',inputSchema:{type:'object',properties:{confirm:{type:'boolean'}},required:['confirm'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:safe(input=>{if(input.confirm!==true)throw new Error('Confirmation required');state=structuredClone(baseProgress);localStorage.removeItem(STORAGE_KEY);currentView='welcome';render();return{reset:true}})})}catch(e){console.warn('WebMCP unavailable',e)}}

function render(){if(currentView==='welcome')welcome();else if(currentView==='dashboard')dashboard();else if(currentView==='lesson')lesson();else if(currentView==='course')course();else if(currentView.startsWith('train:'))train(currentView.split(':')[1]);else if(currentView==='match')matchIQ();else if(currentView==='board')tacticalBoard();else if(currentView==='daily')daily();else if(currentView==='daily-summary')dailySummary();else if(currentView==='cam')camAcademy();else dashboard()}
render();registerWebMCP();
